const server=http.createServer((req,res)=>{const rid=requestId(req);res.setHeader(REQUEST_ID_HEADER,rid);const start=Date.now();console.log(JSON.stringify({time:new Date().toISOString(),level:'INFO',rid,method:req.method,url:req.url,msg:'Request started'}));res.on('finish',()=>console.log(JSON.stringify({time:new Date().toISOString(),level:'INFO',rid,method:req.method,url:req.url,status:res.statusCode,durationMs:Date.now()-start,msg:'Request finished'})));Promise.resolve(route(req,res)).catch(e=>{console.error(JSON.stringify({time:new Date().toISOString(),level:'ERROR',rid,method:req.method,url:req.url,error:e.message,stack:e.stack}));if(!res.headersSent)send(res,e.status||500,{error:e.message||'Erro interno',request_id:rid});else res.destroy()})});server.listen(PORT,()=>console.log(`Xiquim Vargas ERP em http://localhost:${PORT}`));
function shutdown(signal){console.log(`Encerrando por ${signal}...`);try{db.exec('PRAGMA wal_checkpoint(TRUNCATE)')}catch(e){console.error('checkpoint',e.message)}server.close(()=>{try{db.close()}finally{process.exit(0)}});setTimeout(()=>process.exit(1),5000).unref()}
process.on('SIGINT',()=>shutdown('SIGINT'));process.on('SIGTERM',()=>shutdown('SIGTERM'));


